{"hypotheses": [
  {
    "name": "Profitability-Momentum Divergence",
    "mechanism": "Stocks with high profitability but low recent momentum can be undervalued as investor attention focuses on past returns, missing future earnings strength. This composite captures the revaluation when fundamentals (operating profitability) and sentiment (momentum) diverge, potentially compounding the two signals for stronger outperformance than either predictor alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": -0.5, "primitive": "Mom12m"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Shareholder Return Discipline (Buybacks minus Issuance)",
    "mechanism": "Firms simultaneously engaging in share repurchases while avoiding equity issuance demonstrate strong capital discipline, likely signaling management’s conviction in undervaluation and alignment with shareholders. The net effect better isolates intentional capital return from mechanical buybacks or dilution alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": -1.0, "primitive": "ShareIss1Y"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Analyst Disagreement Value",
    "mechanism": "High book-to-market stocks with low analyst forecast dispersion are more likely to be undervalued because they combine objective undervaluation with analyst consensus, suggesting that the value signal is less likely to be a value trap. This reduces the likelihood of idiosyncratic risk mispricing.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Cautious Growth in Low Volatility",
    "mechanism": "Asset growth is typically penalized, but in low volatility (risk-on) markets, investors are more forgiving of growth strategies. By going short asset growth in calm environments, the composite capitalizes on the market's tendency to overpay for perceived safety plus growth.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Profit Surprise Reaction",
    "mechanism": "Combining operating profitability with earnings surprise takes advantage of market underreaction to concurrent positive signals—firms with both strong profitability and positive surprises are more likely to outperform as investor expectations are sequentially revised.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "OperProf"},
        {"weight": 0.5, "primitive": "EarningsSurprise"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Liquidity-Momentum Defensive",
    "mechanism": "Stocks with high momentum but low liquidity beta (less exposed to liquidity shocks) are more robust to market stress, leading to higher risk-adjusted returns as they combine crowd-favorite characteristics with defensiveness to liquidity crises.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -1.0, "primitive": "BetaLiquidityPS"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "BetaLiquidityPS", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Quality Post-Dilution Recovery",
    "mechanism": "Stocks with high cash flow yield but recent equity issuance are typically shunned due to dilution. However, high cash flow may indicate that issuance is for productive investment, enabling superior future performance once the market digests the event.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CF"},
        {"weight": -0.5, "primitive": "ShareIss1Y"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "ShareIss1Y", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "R&D Capital Momentum",
    "mechanism": "Firms with high R&D-to-assets ratios and positive intermediate momentum benefit both from intangible capital investment and investor recognition. The combination exploits underappreciated innovation that is just beginning to be reflected in stock prices.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RDcap"},
        {"weight": 0.5, "primitive": "IntMom"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  }
]}
